"""Bring a project into AutoPatch safely: uploads, zip files, local folders and git clones.

Guards against path traversal, symlinks and decompression bombs. There are no fixed size limits:
limits come from Settings (0 = unlimited), and every file that is not imported is reported with
the reason, never skipped silently.
"""

from __future__ import annotations

import os
import re
import shutil
import stat
import subprocess
import zipfile
from pathlib import Path, PurePosixPath

# Folders that are regenerated by tools (caches, virtualenvs, dependency installs, build output).
# They are not imported, and the import report lists each one with its file count.
SKIP_DIRS = {
    ".git", ".hg", ".svn", ".venv", "venv", "env", "__pycache__", ".pytest_cache", ".mypy_cache",
    ".ruff_cache", ".tox", ".nox", "node_modules", ".idea", ".vscode", "build", "dist", ".autopatch",
    ".eggs", "htmlcov", ".hypothesis", ".next", ".turbo", ".parcel-cache", ".gradle", "target",
}
SKIP_SUFFIXES = (".pyc", ".pyo", ".egg-info")
ZIP_BOMB_RATIO = 1000


class ProjectImportError(ValueError):
    """The upload or import cannot be accepted. The message is shown to the user."""


def safe_relpath(raw: str) -> PurePosixPath:
    text = raw.replace("\\", "/").strip()
    if not text or text.startswith("/") or re.match(r"^[A-Za-z]:", text):
        raise ProjectImportError(f"Rejected unsafe path: {raw!r}")
    parts = [p for p in text.split("/") if p not in ("", ".")]
    if not parts or any(p == ".." for p in parts):
        raise ProjectImportError(f"Rejected unsafe path: {raw!r}")
    return PurePosixPath(*parts)


def skip_reason(rel: PurePosixPath) -> str | None:
    for part in rel.parts[:-1]:
        if part in SKIP_DIRS or part.endswith(SKIP_SUFFIXES):
            return part
    if rel.name.endswith((".pyc", ".pyo")):
        return "*.pyc"
    return None


def is_skipped(rel: PurePosixPath) -> bool:
    return skip_reason(rel) is not None


def _limits() -> dict:
    try:
        from autopatch.core import settings

        cfg = settings.get_all()
        return {"file": cfg["limits.max_file_mb"] * 1024 * 1024, "project": cfg["limits.max_project_mb"] * 1024 * 1024,
                "files": cfg["limits.max_files"]}
    except Exception:  # settings unavailable (e.g. outside the app): no limits
        return {"file": 0, "project": 0, "files": 0}


class Report:
    """Counts what was imported and records everything that was not."""

    def __init__(self) -> None:
        self.limits = _limits()
        self.files = 0
        self.bytes = 0
        self.skipped: list[dict] = []
        self._dir_counts: dict[str, dict] = {}

    def skip_dir(self, rel: str, reason_key: str) -> None:
        entry = self._dir_counts.setdefault(rel, {"path": rel + "/", "files": 0,
                                                  "reason": f"{reason_key} is a generated or tool folder "
                                                            "(caches, dependencies, build output); it is recreated by tools"})
        entry["files"] += 1

    def skip(self, rel: str, reason: str) -> None:
        self.skipped.append({"path": rel, "files": 1, "reason": reason})

    def take(self, rel: PurePosixPath, size: int) -> bool:
        if self.limits["file"] and size > self.limits["file"]:
            self.skip(str(rel), f"{size:,} bytes is above the per-file limit set in Settings ({self.limits['file']:,})")
            return False
        self.files += 1
        self.bytes += size
        if self.limits["files"] and self.files > self.limits["files"]:
            raise ProjectImportError(f"The project has more than {self.limits['files']:,} files (limit set in Settings)")
        if self.limits["project"] and self.bytes > self.limits["project"]:
            raise ProjectImportError(f"The project is larger than {self.limits['project'] // (1024 * 1024):,} MB "
                                     "(limit set in Settings)")
        return True

    def to_dict(self) -> dict:
        return {"imported": self.files, "bytes": self.bytes,
                "skipped": sorted(self.skipped + list(self._dir_counts.values()), key=lambda s: s["path"])}


def copy_tree(src: Path, dest: Path, report: Report | None = None) -> Report:
    report = report or Report()
    src = src.resolve()
    if not src.is_dir():
        raise ProjectImportError(f"Not a folder: {src}")
    for dirpath, dirnames, filenames in os.walk(src, followlinks=False):
        here = Path(dirpath)
        keep = []
        for d in sorted(dirnames):
            rel_d = (here / d).relative_to(src).as_posix()
            if (here / d).is_symlink():
                report.skip(rel_d + "/", "symbolic link (not followed, for safety)")
            elif d in SKIP_DIRS or d.endswith(SKIP_SUFFIXES):
                count = sum(len(f) for _, _, f in os.walk(here / d))
                report._dir_counts[rel_d] = {"path": rel_d + "/", "files": count,
                                             "reason": f"{d} is a generated or tool folder (caches, dependencies, "
                                                       "build output); it is recreated by tools"}
            else:
                keep.append(d)
        dirnames[:] = keep
        for name in sorted(filenames):
            file = here / name
            rel = PurePosixPath(file.relative_to(src).as_posix())
            if file.is_symlink():
                report.skip(str(rel), "symbolic link (not followed, for safety)")
                continue
            if name.endswith((".pyc", ".pyo")):
                report.skip_dir(str(rel.parent) if str(rel.parent) != "." else "", "*.pyc")
                continue
            try:
                size = file.stat().st_size
            except OSError as exc:
                report.skip(str(rel), f"could not be read: {exc}")
                continue
            if not report.take(rel, size):
                continue
            target = dest / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            try:
                shutil.copyfile(file, target)
            except OSError as exc:
                report.files -= 1
                report.skip(str(rel), f"could not be read: {exc}")
    if report.files == 0:
        raise ProjectImportError("The folder has no files to import" +
                                 (f" ({len(report.to_dict()['skipped'])} item(s) were skipped)" if report.skipped or report._dir_counts else ""))
    return report


def common_root(rels: list[PurePosixPath]) -> str | None:
    tops = {r.parts[0] for r in rels}
    if len(tops) == 1 and all(len(r.parts) > 1 for r in rels):
        return next(iter(tops))
    return None


def save_uploaded_files(items: list[tuple[str, bytes]], dest: Path) -> tuple[int, str | None]:
    """Write (relative path, content) pairs (used by tests and small uploads)."""
    if not items:
        raise ProjectImportError("No files were uploaded")
    raw = dest.parent / (dest.name + "-raw")
    for path, data in items:
        rel = safe_relpath(path)
        (raw / rel).parent.mkdir(parents=True, exist_ok=True)
        (raw / rel).write_bytes(data)
    top = common_root([safe_relpath(p) for p, _ in items])
    report = copy_tree(raw / top if top else raw, dest)
    shutil.rmtree(raw, ignore_errors=True)
    return report.files, top


def extract_zip(zip_path: Path, dest: Path, report: Report | None = None) -> tuple[int, str | None]:
    report = report or Report()
    try:
        archive = zipfile.ZipFile(zip_path)
    except zipfile.BadZipFile as exc:
        raise ProjectImportError("The file is not a valid zip archive") from exc
    with archive:
        members = []
        for info in archive.infolist():
            if info.is_dir():
                continue
            if stat.S_ISLNK(info.external_attr >> 16):
                report.skip(info.filename, "symbolic link inside the archive (not extracted, for safety)")
                continue
            members.append((safe_relpath(info.filename), info))
        if not members:
            raise ProjectImportError("The zip archive is empty")
        top = common_root([m[0] for m in members])
        for rel_full, info in members:
            rel = PurePosixPath(*rel_full.parts[1:]) if top else rel_full
            reason = skip_reason(rel)
            if reason or rel.parts[0] == "__MACOSX":
                report.skip_dir(str(rel.parent), reason or "__MACOSX")
                continue
            if info.compress_size and info.file_size / info.compress_size > ZIP_BOMB_RATIO and info.file_size > 100 * 1024 * 1024:
                report.skip(str(rel), f"expands {info.file_size // max(info.compress_size, 1):,}x; treated as a decompression bomb")
                continue
            if not report.take(rel, info.file_size):
                continue
            target = dest / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as src, open(target, "wb") as out:
                written = 0
                while chunk := src.read(1024 * 1024):  # streamed, never fully in memory
                    written += len(chunk)
                    if written > info.file_size + 1024:
                        raise ProjectImportError(f"{rel} expands beyond its declared size; the archive is unsafe")
                    out.write(chunk)
    if report.files == 0:
        raise ProjectImportError("The zip archive has no importable files")
    return report.files, top


_GIT_URL = re.compile(r"^(https://[\w.\-]+(:\d+)?/[\w.\-/~%]+|git@[\w.\-]+:[\w.\-/~]+)$")


def clone_git(url: str, dest: Path, timeout_s: int = 600) -> None:
    url = url.strip()
    if not _GIT_URL.match(url):
        raise ProjectImportError("Enter an https:// or git@ repository URL")
    env = os.environ.copy()
    env["GIT_TERMINAL_PROMPT"] = "0"
    try:
        proc = subprocess.run(
            ["git", "clone", "--depth", "1", "--no-tags", "--single-branch", "--", url, str(dest)],
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=timeout_s, env=env,
        )
    except subprocess.TimeoutExpired as exc:
        raise ProjectImportError(f"git clone took longer than {timeout_s}s") from exc
    if proc.returncode != 0:
        raise ProjectImportError(f"git clone failed: {proc.stderr.strip()[-400:]}")
    shutil.rmtree(dest / ".git", ignore_errors=True, onexc=_force_remove)


def _force_remove(func, path, _exc) -> None:
    os.chmod(path, stat.S_IWRITE)
    func(path)


def rmtree(path: Path) -> None:
    if path.exists():
        shutil.rmtree(path, onexc=_force_remove)


def looks_binary(data: bytes) -> bool:
    return b"\x00" in data[:8192]
